using System.Text.Json.Serialization;
using Shop.SharedKernel;
namespace Shop.Modules.Credit;
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed record CreditClearanceInput(string Action,string OrderVersion,[property:JsonRequired][property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]string? Version,string PreviewFingerprint,string Note,[property:JsonRequired]bool Confirmed,[property:JsonIgnore(Condition=JsonIgnoreCondition.WhenWritingDefault)]bool AcknowledgedPartialDispatch=false);
public sealed record CreditClearanceCheque(int Sequence,string DueDate,string AmountRial,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]string? ChequeId,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]string? LedgerVersion,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]string? LedgerState,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]string? ApprovalId,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]string? ApprovalVersion,bool Approved);
public sealed record CreditClearanceEvidence(string FinancialFingerprint,string QuoteFingerprint,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]string? ScheduleId,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]string? ScheduleVersion,string RequiredUpfrontRial,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]string? UpfrontId,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]string? UpfrontVersion,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]string? UpfrontState,bool UpfrontConfirmed,CreditClearanceCheque[] Cheques,bool AllChequesApproved);
public sealed record CreditClearanceSummary(string Id,string OrderId,int Sequence,string Action,string State,string Version,string EvidenceFingerprint,string SourceOrderVersion,string ResultOrderVersion,DateTimeOffset RecordedAt,bool BankVerified=false);
public sealed record CreditClearanceEventData(CreditClearanceSummary Summary,string Note,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]string? PreviousVersion,[property:JsonIgnore(Condition=JsonIgnoreCondition.WhenWritingDefault)]bool AcknowledgedPartialDispatch=false);
public sealed record CreditClearancePage(int SchemaVersion,string OrderId,string OrderVersion,string OrderState,string ReservationState,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]string? ShipmentState,CreditClearanceEvidence Evidence,string EvidenceFingerprint,string PreviewFingerprint,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]CreditClearanceSummary? Current,bool Effective,bool CanApprove,bool CanRevoke,string[] Blockers,bool BankVerified=false,bool CanPay=false);
public sealed record CreditClearanceCustomerPage(int SchemaVersion,string OrderId,string OrderState,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]CreditClearanceSummary? Current,bool Effective,bool BankVerified=false,bool CanPay=false);
public sealed record CreditClearanceHistory(int SchemaVersion,string OrderId,CreditClearanceEventData[] Items,[property:JsonIgnore(Condition=JsonIgnoreCondition.Never)]int? NextBefore);
public sealed record CreditClearanceResult(int SchemaVersion,string CommandId,string OrderId,CreditClearanceEventData Event,bool InitialCommit,bool Replayed,bool BankVerified=false,bool CanPay=false);
public interface ICreditClearanceProtection{byte[] Protect(string purpose,string principal,string order,string id,string text);string Unprotect(string purpose,string principal,string order,string id,byte[] bytes);}
public static class CreditClearanceRules
{
    public const int MaxEvents=200;
    public static BusinessException Invalid()=>new("invalid_credit_clearance","Review the server financial evidence, explicit action, versions and confirmation.");
    public static BusinessException Conflict()=>new("credit_clearance_changed_conflict","The financial evidence, order, deadline or shipment changed; review the current facts.");
    public static BusinessException Unavailable()=>new("credit_clearance_unavailable","The independent credit financial authorization could not be verified.");
    public static BusinessException Immutable()=>new("credit_clearance_history_immutable","Credit financial authorizations and receipts cannot be modified or removed.");
    public static void Validate(CreditClearanceInput x){if(x is null||!x.Confirmed||x.Action is not("Approve"or"Revoke")||x.Action=="Revoke"&&x.Version is null||x.AcknowledgedPartialDispatch&&x.Version is null)throw Invalid();CreditApplicationRules.Version(x.OrderVersion);if(x.Version is{}v)CreditApplicationRules.Version(v);CreditApplicationRules.Digest(x.PreviewFingerprint);CreditUpfrontRules.Text(x.Note,500,!x.AcknowledgedPartialDispatch);}
    public static bool Eligible(CreditClearanceEvidence e)=>e.ScheduleId is not null&&e.ScheduleVersion is not null&&e.UpfrontConfirmed&&e.AllChequesApproved&&e.Cheques.Length is>0 and<=60&&e.Cheques.All(x=>x.Approved&&x.ChequeId is not null&&x.ApprovalId is not null&&x.ApprovalVersion is not null&&x.LedgerVersion is not null&&ChequeApprovalRules.Eligible(x.LedgerState??""));
}
